import {R,part,previous,question as q} from './practice-shared.js';
const source='Eigene Anwendung · Lecture Notes 1.11; Rechenguide S. 2–4; Grundaufgabentyp im Erinnerungsbericht 2026';
export const compactTasks=[
 {...previous('a-compact',[1]),id:'k-annulus',family:'closed',level:0,title:'Halbring',source,purpose:'Mehrere abgeschlossene Bedingungen und eine gemeinsame Normschranke verbinden.',
 questions:[q('Welche beiden Eigenschaften reichen hier für Kompaktheit?','Abgeschlossenheit und Beschränktheit.','Die Menge liegt in einem endlichdimensionalen euklidischen Raum: Heine–Borel gilt.','Nur Beschränktheit.','Eine offene Kreisscheibe ist beschränkt und trotzdem nicht kompakt.','Nur Abgeschlossenheit.','Eine abgeschlossene Halbgerade ist unbeschränkt und nicht kompakt.')],
 hints:[R`Nutze $q(x,y)=x^2+y^2$ und $p(x,y)=x$.`,R`Schreibe $K=q^{-1}([1,4])\cap p^{-1}([0,\infty))$.`,R`Aus $x^2+y^2\le4$ folgt $\|(x,y)\|\le2$.`] },
 {id:'k-ellipse',family:'closed',level:1,title:'Ellipse mit Zusatzbedingung',source,purpose:'Auch ohne unmittelbar vorgegebene Normquadratschranke eine einfache Schranke gewinnen.',intro:'',
 parts:[part(R`Ist $K=\{(x,y):x^2+4y^2\le4,\ x+y\ge0\}$ kompakt? Begründe.`,
 R`**Abgeschlossenheit:** Setze $q(x,y)=x^2+4y^2$ und $p(x,y)=x+y$. Beide Funktionen sind auf ganz $\mathbb R^2$ stetig, und es gilt $$K=q^{-1}((-\infty,4])\cap p^{-1}([0,\infty)).$$ Die Mengen $(-\infty,4]$ und $[0,\infty)$ sind abgeschlossen. Ihre Urbilder und deren Schnitt sind abgeschlossen. Also ist $K$ abgeschlossen.`,
 R`**Beschränktheit:** Für jeden Punkt $(x,y)\in K$ gilt $$x^2+y^2\le x^2+4y^2\le4.$$ Daher ist $\|(x,y)\|=\sqrt{x^2+y^2}\le2$. Also ist $K$ beschränkt.`,
 R`**Schluss:** $K$ ist abgeschlossen und beschränkt, also nach Heine–Borel kompakt.`)],
 questions:[q('Wie erhältst du eine Normschranke? ',R`$x^2+y^2\le x^2+4y^2\le4$.`,'Beide Quadrate sind nichtnegativ; der Vergleich ergibt unmittelbar eine gemeinsame Schranke.',R`$x^2+y^2=x^2+4y^2$.`,'Die Gleichheit gilt nur bei y = 0, nicht für alle Punkte.',R`$x+y\ge0$ beschränkt bereits die Norm.`,'Eine Halbebene enthält beliebig weit entfernte Punkte.')],
 hints:[R`Alle Ausdrücke in den Bedingungen sind Polynome.`,R`Die erlaubten Wertebereiche $(-\infty,4]$ und $[0,\infty)$ sind abgeschlossen.`,R`Vergleiche $x^2+y^2$ mit $x^2+4y^2$.`] },
 {id:'k-open',family:'noncompact',level:0,title:'Kreisscheibe ohne Rand',source,purpose:'Einen fehlenden Randpunkt durch eine konkrete Folge nachweisen.',intro:'',
 parts:[part(R`Ist $M=\{(x,y):x^2+y^2<1\}$ kompakt? Gib einen vollständigen Nachweis.`,R`Für $n\ge1$ liegt $z_n=(1-1/n,0)$ in $M$, denn $(1-1/n)^2<1$.`,R`Es gilt $z_n\to(1,0)\notin M$. Daher ist $M$ nicht abgeschlossen und nach Heine–Borel nicht kompakt.`)],
 questions:[q('Welche Folge widerlegt Abgeschlossenheit?',R`$z_n=(1-1/n,0)$.`,R`Alle Folgenglieder liegen in $M$, der Grenzwert $(1,0)$ nicht.`,R`$z_n=(1+1/n,0)$.`,'Diese Punkte liegen nicht in der Menge und können den Nachweis daher nicht liefern.',R`$z_n=(1/n,0)$ für $n\ge2$.`,'Diese Folge konvergiert gegen einen Punkt innerhalb der Menge.')],
 hints:[R`Suche einen Punkt auf dem Rand $x^2+y^2=1$.`,R`Nähere dich $(1,0)$ von innen auf der x-Achse.`,R`Prüfe sowohl $z_n\in M$ als auch den Grenzwert außerhalb.`] },
 {...previous('b-compact',[1]),id:'k-hyperbola',family:'noncompact',level:2,title:'Abgeschlossen und trotzdem nicht kompakt',purpose:'Unbeschränktheit von fehlender Abgeschlossenheit unterscheiden.',
 questions:[q('Welcher Nachweis genügt für Nichtkompaktheit?',R`$(1/n,n)\in M$ und die Norm geht gegen unendlich.`,'Damit ist Unbeschränktheit gezeigt, unabhängig von der Abgeschlossenheit.','Die Bedingung x > 0 allein beweist, dass M nicht abgeschlossen ist.','Entscheidend ist die ganze Menge: xy = 1 verhindert hier einen endlichen Grenzpunkt mit x = 0.','Der Nenner wird nie null, also ist M kompakt.','Ein überall definierter Nenner auf der Menge liefert keine Beschränktheit.')],
 hints:[R`Setze $x=1/n$. Die zweite Koordinate ist dann $n$.`,R`Die Norm ist mindestens $n$.`,R`Für Abgeschlossenheit: Nutze $q(x,y)=xy$ und $p(x,y)=x$. Dann ist $M=q^{-1}(\{1\})\cap p^{-1}([0,1])$. Die Bedingung $xy=1$ schließt $x=0$ aus.`] },
 {...previous('a-compact',[2]),id:'k-sequence',family:'noncompact',level:1,title:'Folge mit und ohne Grenzpunkt',source:'Eigene Variante · Lecture Notes Beispiel 3, Satz 1.11; Rechenguide S. 4',purpose:'Dieselbe beschränkte Punktmenge mit und ohne ihren Grenzpunkt vergleichen.',
 questions:[q('Was ändert das Hinzufügen von (0,0)?','Der einzige fehlende Häufungspunkt wird ergänzt.','Eine offene Umgebung des Grenzpunkts enthält den ganzen Folgenschwanz; nur endlich viele Punkte bleiben übrig.','Dadurch wird die zuvor unbeschränkte Menge beschränkt.','Schon ohne den Ursprung liegen alle Punkte in einer festen Kugel.','Nichts: unendlich viele Punkte können nicht kompakt sein.','Kompakte Mengen dürfen unendlich viele Punkte enthalten, beispielsweise ein abgeschlossenes Intervall.')],
 hints:[R`Berechne den Grenzwert von $(1/n,1/n^2)$.`,R`Für die ergänzte Menge nimm eine beliebige offene Überdeckung und eine ihrer Mengen um $(0,0)$.`,R`Diese enthält ab einem Index alle Folgenglieder. Decke die endlich vielen übrigen Punkte einzeln ab.`] },
 {...previous('b-compact',[0]),id:'k-graph',family:'images',level:0,title:'Ein kompakter Graph',source:'Eigene Anwendung · Lecture Notes 1.12; stetige Bilder kompakter Mengen',purpose:'Einen Graphen unmittelbar als stetiges Bild eines kompakten Intervalls erkennen.',
 questions:[q('Welche Darstellung liefert den kürzesten vollständigen Nachweis?',R`$K=\varphi([1,2])$ mit $\varphi(t)=(t,1/t)$.`,R`$[1,2]$ ist kompakt und $\varphi$ dort stetig. Damit ist ihr Bild kompakt.`,R`$K=\varphi((0,\infty))$.`,'Das wäre eine andere Menge, und die Ausgangsmenge wäre nicht kompakt.','Jeder Graph einer stetigen Funktion ist kompakt.','Es fehlt eine kompakte Ausgangsmenge; etwa der Graph von t auf R ist unbeschränkt.')],
 hints:[R`Welche eindimensionale Menge parametrisiert den ganzen Graphen?`,R`Verwende $\varphi(t)=(t,1/t)$ auf $[1,2]$.`,R`Nenne Kompaktheit des Intervalls, Stetigkeit und die Gleichheit des Bildes mit $K$.`] },
 {id:'k-operations',family:'images',level:1,title:'Summen, Produkte und Quotienten',source:'Anwendung von B.3.4(a,c,d) · Rechenguide S. 4a–4b',sourceHref:'#/blaetter/3/B.3.4',purpose:'Stetige Bilder kompakter Mengen verwenden und beim Quotienten die Zusatzbedingung am Nenner prüfen.',intro:R`Sei $A\subset\mathbb R$ kompakt.`,
 parts:[part(R`Zeige, dass $S=\{x+y:x,y\in A\}$ und $P=\{xy:x,y\in A\}$ kompakt sind.`,
 R`**Ausgangsmenge:** Da $A$ kompakt ist, ist auch $K=A\times A$ kompakt.`,
 R`**Summe:** Definiere $f:\mathbb R^2\to\mathbb R$ durch $f(x,y)=x+y$. Die Funktion $f$ ist stetig, und es gilt $$S=\{x+y:x,y\in A\}=f(K).$$ Als stetiges Bild der kompakten Menge $K$ ist $S$ kompakt.`,
 R`**Produkt:** Definiere $g:\mathbb R^2\to\mathbb R$ durch $g(x,y)=xy$. Auch $g$ ist stetig, und es gilt $$P=\{xy:x,y\in A\}=g(K).$$ Als stetiges Bild der kompakten Menge $K$ ist auch $P$ kompakt.`),
 part(R`Ist auch $Q=\{x/y:x,y\in A,\ y\ne0\}$ immer kompakt? Was gilt zusätzlich bei $0\notin A$?`,
 R`**Nicht immer: Gegenbeispiel.** Wähle $A=[0,1]$. Dieses Intervall ist abgeschlossen und beschränkt, also nach Heine–Borel kompakt.`,
 R`Für jedes $n\ge1$ liegen $x=1$ und $y=1/n$ in $A$, und $y\ne0$. Daher gilt $$\frac{x}{y}=\frac{1}{1/n}=n\in Q.$$ Somit enthält $Q$ beliebig große Zahlen, ist unbeschränkt und nicht kompakt.`,
 R`**Mit $0\notin A$ ist $Q$ kompakt.** Die Menge $K=A\times A$ ist kompakt. Weil kein Nenner null ist, ist die Abbildung $$q:K\to\mathbb R,\qquad q(x,y)=\frac{x}{y}$$ auf ganz $K$ definiert und stetig. Es gilt $Q=q(K)$. Also ist $Q$ als stetiges Bild einer kompakten Menge kompakt.`)],
 questions:[q('Was muss beim Quotienten zusätzlich geprüft werden?','Ob die Division auf der gesamten kompakten Ausgangsmenge definiert und stetig ist.','Das Entfernen der Null aus einer kompakten Menge kann die Kompaktheit der Ausgangsmenge zerstören.','Ob jede einzelne Division einen endlichen Wert hat.','Einzelne endliche Werte können insgesamt unbeschränkt sein.','Ob A endlich ist.','Endlichkeit ist nicht notwendig; auch kompakte Intervalle ohne Null funktionieren.')],
 hints:[R`Nutze als Ausgangsmenge $A\times A$.`,R`Addition und Multiplikation sind überall stetig; Division nicht bei Nenner 0.`,R`Teste $A=[0,1]$ mit Zähler $1$ und Nenner $1/n$.`] },
 {id:'k-unions',family:'images',level:2,title:'Mengenoperationen konkret anwenden',source:'Eigene konkrete Variante · B.3.3; Lecture Notes 1.12',sourceHref:'#/blaetter/3/B.3.3',purpose:'Endliche und unendliche Vereinigung sowie einen Schnitt unterscheiden.',intro:R`Sei $K_n=[-1/n,1/n]$ für $n\ge1$.`,
 parts:[part(R`Bestimme $\bigcap_{n\ge1}K_n$ und $K_1\cup K_2$. Sind sie kompakt?`,
 R`**Schnitt bestimmen:** Die Zahl $0$ liegt in jedem $K_n$. Liegt umgekehrt $x$ im Schnitt, so gilt $|x|\le1/n$ für jedes $n\ge1$. Wegen $1/n\to0$ folgt $|x|=0$, also $x=0$. Somit $$\bigcap_{n\ge1}K_n=\{0\}.$$ Die Menge $\{0\}$ ist abgeschlossen und beschränkt, also nach Heine–Borel kompakt.`,
 R`**Vereinigung bestimmen:** Es gilt $$K_1=[-1,1],\qquad K_2=[-1/2,1/2]\subseteq K_1.$$ Deshalb ist $$K_1\cup K_2=[-1,1].$$ Dieses Intervall ist abgeschlossen und beschränkt, also nach Heine–Borel kompakt.`),
 part(R`Ist $U=\bigcup_{n\ge1}[0,n]$ kompakt?`,
 R`**Vereinigung bestimmen:** Alle Intervalle $[0,n]$ enthalten nur nichtnegative Zahlen. Umgekehrt liegt jedes $x\ge0$ in einem solchen Intervall: Wähle eine natürliche Zahl $n\ge1$ mit $n\ge x$. Dann ist $x\in[0,n]$. Daher $$U=\bigcup_{n\ge1}[0,n]=[0,\infty).$$`,
 R`**Kompaktheit prüfen:** Für jedes $n\ge1$ gilt $n\in U$ und $|n|=n\to\infty$. Also ist $U$ unbeschränkt und nicht kompakt. Jedes einzelne Intervall $[0,n]$ ist kompakt; ihre unendliche Vereinigung ist es hier nicht.`)],
 questions:[q('Welche Vereinigung erhält Kompaktheit stets?','Eine endliche Vereinigung kompakter Mengen.','Das ist eine Stabilitätseigenschaft; für unendliche Vereinigungen gilt sie nicht allgemein.','Jede abzählbare Vereinigung kompakter Mengen.',R`$\bigcup_n[0,n]=[0,\infty)$ ist ein Gegenbeispiel.`,'Nur eine Vereinigung disjunkter kompakter Mengen.','Disjunktheit ist für die endliche Vereinigung nicht erforderlich.')],
 hints:[R`Ein Punkt ungleich 0 liegt für genügend große $n$ nicht mehr in $K_n$.`,R`$K_2\subset K_1$.`,R`Jede nichtnegative reelle Zahl liegt in irgendeinem $[0,n]$.`] }
];
